from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')
login_manager = LoginManager()
def task_func(secret_key, template_folder):
    """Build and return a Flask app configured for user authentication.

    The returned application provides:
      * ``/login``   -- form based login (Flask-WTF, CSRF protected by default)
      * ``/``        -- protected landing page for the logged in user
      * ``/protected`` -- explicitly protected page for the logged in user
      * ``/logout``  -- logs the user out and redirects to ``/login``

    Everything is derived from the ``secret_key`` / ``template_folder``
    arguments, so the function can safely be called many times (each call
    returns a fully independent application).
    """
    from datetime import timedelta
    from urllib.parse import urlsplit

    from flask import flash, request
    from jinja2 import ChoiceLoader, DictLoader, FileSystemLoader

    # ------------------------------------------------------------------
    # 1. Application + dynamic security configuration
    # ------------------------------------------------------------------
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key
    app.config['WTF_CSRF_ENABLED'] = True
    app.config['WTF_CSRF_TIME_LIMIT'] = timedelta(hours=1)
    app.config['SESSION_COOKIE_HTTPONLY'] = True
    app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'
    app.config['REMEMBER_COOKIE_HTTPONLY'] = True
    app.config['REMEMBER_COOKIE_DURATION'] = timedelta(days=7)
    app.config['PERMANENT_SESSION_LIFETIME'] = timedelta(days=1)

    # ------------------------------------------------------------------
    # 2. In-memory user store (rebuilt on every call -> no stale state)
    # ------------------------------------------------------------------
    store = _build_user_store()
    USERS.clear()
    USERS.update(store)
    app.config['USERS'] = store

    # ------------------------------------------------------------------
    # 3. Flask-Login setup (idempotent, works across several apps)
    # ------------------------------------------------------------------
    login_manager.init_app(app)
    login_manager.login_view = 'login'
    login_manager.login_message = 'Please log in to access this page.'
    login_manager.login_message_category = 'warning'
    login_manager.session_protection = 'strong'

    @login_manager.user_loader
    def load_user(user_id):
        """Resolve a user id from this application's in-memory store."""
        users = app.config.get('USERS') or USERS
        user = users.get(user_id)
        if user is None:
            return None
        return user

    # ------------------------------------------------------------------
    # 4. Templates: a caller supplied folder wins, inline ones fall back
    # ------------------------------------------------------------------
    loaders = []
    if app.template_folder:
        try:
            loaders.append(FileSystemLoader(app.template_folder))
        except TypeError:  # pragma: no cover - defensive
            pass
    loaders.append(DictLoader(DEFAULT_TEMPLATES))
    app.jinja_loader = ChoiceLoader(loaders)

    # ------------------------------------------------------------------
    # 5. Routes
    # ------------------------------------------------------------------
    def _redirect_target(default_endpoint='protected'):
        """Return a safe, local redirect target from the ``next`` argument."""
        return _safe_next(request.args.get('next'), url_for(default_endpoint))

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        if current_user.is_authenticated:
            return redirect(_redirect_target())

        form = LoginForm()
        if form.validate_on_submit():
            user = app.config['USERS'].get(form.username.data)
            if user is not None and user.check_password(form.password.data):
                login_user(user, remember=True)
                return redirect(_redirect_target())
            flash('Invalid username or password.', 'danger')

        return render_template('login.html', form=form)

    @app.route('/')
    @login_required
    def index():
        return render_template('index.html', user=current_user)

    @app.route('/protected')
    @login_required
    def protected():
        return render_template('protected.html', user=current_user)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        flash('You have been logged out.', 'info')
        return redirect(url_for('login'))

    return app


# ======================================================================
# Module level declarations (no side effects: no app is created here)
# ======================================================================

#: Demo credentials seeded into the in-memory store.  Both username
#: (4-25 chars) and password (8-80 chars) satisfy the form validators.
_DEMO_CREDENTIALS = {
    'testuser': 'password123',
    'adminuser': 'adminpass123',
}

#: Public, inspectable / extendable in-memory user store.
USERS = {}


class User(UserMixin):
    """Minimal user object backed by an in-memory password hash."""

    def __init__(self, username, password_hash):
        self.username = username
        self.password_hash = password_hash

    @property
    def id(self):
        return self.username

    def get_id(self):
        return self.username

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

    def __repr__(self):  # pragma: no cover - debugging helper
        return '<User {0!r}>'.format(self.username)


def _build_user_store():
    """Create a fresh ``{username: User}`` mapping."""
    return {
        username: User(username, generate_password_hash(password))
        for username, password in _DEMO_CREDENTIALS.items()
    }


def _safe_next(target, fallback):
    """Only allow local, single-slash relative redirect targets."""
    if not target or not isinstance(target, str):
        return fallback
    cleaned = target.replace('\\', '').replace('\r', '').replace('\n', '').strip()
    if not cleaned or not cleaned.startswith('/') or cleaned.startswith('//'):
        return fallback
    parsed = urlsplit(cleaned)
    if parsed.scheme or parsed.netloc:
        return fallback
    return cleaned


DEFAULT_TEMPLATES = {
    'login.html': """<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Log In</title></head>
<body>
  <h1>Log In</h1>
  {% with messages = get_flashed_messages(with_categories=true) %}
    {% if messages %}
      <ul class="flashes">
      {% for category, message in messages %}
        <li class="{{ category }}">{{ message }}</li>
      {% endfor %}
      </ul>
    {% endif %}
  {% endwith %}
  <form method="post" action="{{ url_for('login', next=request.args.get('next')) }}">
    {{ form.hidden_tag() }}
    <p>
      {{ form.username.label }}<br>
      {{ form.username(size=32) }}
      {% for error in form.username.errors %}<span class="error">{{ error }}</span>{% endfor %}
    </p>
    <p>
      {{ form.password.label }}<br>
      {{ form.password(size=32) }}
      {% for error in form.password.errors %}<span class="error">{{ error }}</span>{% endfor %}
    </p>
    <p>{{ form.submit() }}</p>
  </form>
</body>
</html>
""",
    'index.html': """<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Home</title></head>
<body>
  <h1>Welcome, {{ user.username }}!</h1>
  <p>You are logged in.</p>
  <p><a href="{{ url_for('protected') }}">Protected page</a> |
     <a href="{{ url_for('logout') }}">Log out</a></p>
</body>
</html>
""",
    'protected.html': """<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Protected</title></head>
<body>
  <h1>Protected Page</h1>
  <p>Hello, {{ user.username }}. This page requires authentication.</p>
  <p><a href="{{ url_for('index') }}">Home</a> |
     <a href="{{ url_for('logout') }}">Log out</a></p>
</body>
</html>
""",
}
